from util import *
def arx_fr(files,dec,na,nb,inputs,tmin=0):
    Phi=[];Y=[]
    for f in files:
        d=load(f); d=d[d.t>=tmin].iloc[::dec]
        y=d.Q.values-d.Q.values[0]
        U=[]
        for nm in inputs:
            if nm=='e': U.append((d.Vs-d.V).values-(d.Vs-d.V).values[0])
            if nm=='V': U.append(d.V.values-d.V.values[0])
            if nm=='dth': U.append(np.diff(d.th.values,prepend=d.th.values[0]))
            if nm=='Vs': U.append(d.Vs.values-d.Vs.values[0])
        n=len(y); K=max(na,nb)
        cols=[np.r_[np.zeros(k),y[:-k]] for k in range(1,na+1)]
        for u in U: cols+=[np.r_[np.zeros(k),u[:n-k]] if k else u for k in range(0,nb)]
        Phi.append(np.array(cols).T[K:]);Y.append(y[K:])
    Phi=np.vstack(Phi);Y=np.concatenate(Y)
    th=np.linalg.lstsq(Phi,Y,rcond=None)[0]
    T=dec*0.001
    print(files,inputs,'rms',np.sqrt(np.mean((Y-Phi@th)**2)))
    for f in [0.05,0.1,0.2,0.4,0.6,0.8,1,2,5]:
        z=np.exp(1j*2*np.pi*f*T)
        A=1-sum(th[k]*z**-(k+1) for k in range(na))
        out=[]
        for j in range(len(inputs)):
            B=sum(th[na+j*nb+k]*z**-k for k in range(nb))
            if inputs[j]=='dth': B*=(1-1/z)
            g=B/A; out.append('%7.3f∠%6.1f'%(abs(g),np.angle(g,deg=True)))
        print('  f=%.2f'%f,'  '.join(out))
